const params=new URLSearchParams(location.search),focusKnowledge=params.get('focus')||'',book=window.YUANLAI_BOOKS.find(x=>x.id===params.get('book'))||window.YUANLAI_BOOKS[0];let unit=Math.max(0,Math.min(book.chapters.length-1,+params.get('unit')||0)),section=0,stage=0;document.documentElement.style.setProperty('--accent',book.color);const deep=book.id==='math7b'?(unit===0?window.MATH7B_CH7:window.MATH7B_REST?.[unit]):window.SUBJECT_DEEP?.[book.id]?.[unit]||null;if(deep)book.chapters[unit].sections=deep.sections;
