let knowledgeIndex=0,tutorLevel=0;
function currentKnowledge(){const list=knowledgePoints();if(focusKnowledge){const i=list.findIndex(x=>x===focusKnowledge||x.includes(focusKnowledge)||focusKnowledge.includes(x));if(i>=0)knowledgeIndex=i}return list[Math.min(knowledgeIndex,Math.max(0,list.length-1))]||book.chapters[unit].sections[section]}
function localCurriculumCode(){
 const s=book.chapters[unit].sections[section],m=s.match(/^(\d+\.\d+)/);
 if(book.id==='math7b'&&m)return 'M7B-'+m[1];
 if(book.id==='phy8a')return 'P8A-'+(unit+1)+'.'+(section+1);
 if(book.id==='phy8b')return 'P8B-'+(unit+7)+'.'+(section+1);
 if(book.id==='eng7a')return unit<3?'E7A-S'+(unit+1):'E7A-'+(unit-2);
 if(book.id==='eng7b')return 'E7B-'+(unit+1);
 return null;
}
function localHash(text){let h=2166136261;for(const ch of String(text||'')){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return(h>>>0).toString(36)}
function learningContext(extra={}){
 const raw={book:book.id,uiBookId:book.id,subject:book.subject,chapter:book.chapters[unit].title,sectionTitle:book.chapters[unit].sections[section],knowledge:currentKnowledge(),...extra};
 if(window.StudyMateLearningIdentity)return window.StudyMateLearningIdentity.resolve(raw);
 const curriculumCode=localCurriculumCode(),same=String(raw.knowledge||'').trim()===String(raw.sectionTitle||'').trim();
 const mathParent=/^\d+\.\d+\s/.test(raw.sectionTitle||'')&&!/^\d+\.\d+\.\d+/.test(raw.sectionTitle||'');
 const root=same&&(book.id==='phy8a'||book.id==='phy8b'||(book.id==='math7b'&&mathParent));
 return curriculumCode?{...raw,curriculumCode,learningId:root?curriculumCode+'::root':curriculumCode+'::k:'+localHash(raw.knowledge),parentKnowledge:raw.sectionTitle}:raw;
}
