 const common=['concept','concept','concept','concept','procedure','explanation','transfer','retention'];
 if(book.subject==='物理')return ['concept','experiment','evidence','evidence','procedure','explanation','transfer','mastery-check'][stage];
 if(book.subject==='英语'){const k=currentKnowledge();if(/^Speaking|^Writing|^AI Conversation/.test(k))return ['concept','speaking','speaking','concept','procedure','explanation','conversation','mastery-check'][stage];if(/^Listening/.test(k))return ['concept','procedure','procedure','concept','procedure','explanation','transfer','mastery-check'][stage];return ['concept','concept','procedure','concept','procedure','explanation','transfer','mastery-check'][stage]}
 return stage===7?'mastery-check':common[stage];
