function crossMission(){
 const verified=verifiedLesson();if(verified)return verified.cross;
 if(book.id==='math7b'&&unit===0)return{title:'修复天文台平行光轨',copy:'转动光束并读取角度。先用数学判断角关系，再用物理解释光路方向，最后用英语说出 parallel、perpendicular 或 vertical angles。',options:['用角度证据判断光轨关系，并说明方向','只看两条线像不像平行','只记住英文术语'],success:'连接完成：角度证据 → 光路方向 → 英语表达。你使用的是同一个关系，不是三张互不相关的知识卡。'};
 if(book.id==='phy8a'&&unit===0)return{title:'校园运动数据侦测',copy:'读取位置—时间数据，计算速度并判断运动方向，再用英语完成一句数据报告。',options:['先读坐标与单位，再算速度并描述方向','只背速度公式','只翻译 motion 这个单词'],success:'连接完成：坐标图提供数据，物理模型解释运动，英语负责准确报告结果。'};
 if(book.id==='eng7b'&&unit===0)return{title:'动物运动观察报告',copy:'观察动物的身体结构与运动数据，选择恰当形容词，并用完整英语句子报告一次测量结果。',options:['观察结构、记录数据，再用完整句表达','只背 animal 单词','只看动物图片'],success:'连接完成：生物结构解释运动差异，数学记录数据，英语完成真实表达。'};
 return{title:'元来通 · 共同任务',copy:book.chapters[unit].cross.copy,options:['用本课概念解决另一个学科中的真实问题','只看术语卡','跳过条件直接猜答案'],success:'迁移完成：你已经把本课母规则用于另一个学科的真实问题。'};
}
function crossVisual(){
 const mission=crossMission(),source=book.subject,target=mission.subject||book.chapters[unit].cross.subject;
 const labels=mission.labels||(book.subject==='英语'?['观察情境','记录数据','用英语报告']:book.subject==='物理'?['观察现象','处理数据','说明规律']:['读取条件','建立关系','跨学科解释']);
 if(book.id==='eng7a'&&unit===9){const cases=[{min:0,max:10,value:10,label:'酸奶瓶数（目标：150元预算）',reading:'10瓶酸奶：85+30+50=165元，超支15元。',help:'先用150－85－30算酸奶预算，再除以每瓶5元。'},{min:42,max:55,value:42,label:'一年后同一棵树的高度（厘米）',reading:'初始42厘米；一年后42厘米；增长0厘米。',help:'设明年读数49厘米，求明年减今年的高度。'},{min:11,max:23,value:11,label:'第二位同学的生日（日，7月）',reading:'11th→11th→23rd；间隔0天、12天。',help:'请让第二位同学的生日排在11日和23日之间，且与第一位间隔10天。'}],c=cases[section];return `<div class="cross-workbench"><div class="cross-route"><span>${source}</span><b>→</b><span>${target}</span><b>→</b><span>共同任务</span></div><h3>${mission.title}</h3><p>${mission.copy}</p><div class="cross-steps">${labels.map((x,i)=>`<button data-cross-step="${i}"><i>${i+1}</i><span>${x}</span></button>`).join('')}</div><div class="cross-simulator"><label>${c.label} <input id="crossControl" type="range" min="${c.min}" max="${c.max}" value="${c.value}"></label><output id="crossReading">${c.reading}</output><div class="cross-meter"><i></i></div></div><p id="crossResult">${c.help} 调整数值后按顺序完成三步。</p></div>`}
 return `<div class="cross-workbench"><div class="cross-route"><span>${source}</span><b>→</b><span>${target}</span><b>→</b><span>共同任务</span></div><h3>${mission.title}</h3><p>${mission.copy}</p><div class="cross-steps">${labels.map((x,i)=>`<button data-cross-step="${i}"><i>${i+1}</i><span>${x}</span></button>`).join('')}</div><div class="cross-simulator"><label>改变条件 <input id="crossControl" type="range" min="0" max="100" value="35"></label><output id="crossReading">观测值 35</output><div class="cross-meter"><i></i></div></div><p id="crossResult">先改变条件，再依次完成三个步骤。</p></div>`;
}
function activateCrossVisual(){
 $('visualTitle').textContent='跨学科共同任务 · '+book.chapters[unit].sections[section];
 $('visualBody').innerHTML=crossVisual();
 const control=$('crossControl'),reading=$('crossReading'),meter=document.querySelector('.cross-meter i'),result=$('crossResult');
 if(book.id==='eng7a'&&unit===9){const currentSection=section,targets=[7,49,21],target=targets[currentSection],readings=[v=>`${v}瓶酸奶：85+6×5+5×${v}=${115+5*v}元；与150元预算相差${Math.abs(35-5*v)}元。`,v=>`同一棵树：今年42厘米，明年${v}厘米，增长${v-42}厘米。`,v=>`7月11th→${v}${v===21?'st':v===22?'nd':v===23?'rd':'th'}→23rd；两段间隔${v-11}天、${23-v}天。`];const update=()=>{const v=+control.value;reading.textContent=readings[currentSection](v);meter.style.width=(100*(v-(+control.min))/(+control.max-(+control.min)))+'%';if(result.textContent.startsWith('任务完成')&&v!==target)result.textContent='条件已改变，请重新核对计算结果。'};control.oninput=update;document.querySelectorAll('[data-cross-step]').forEach((button,i)=>button.onclick=()=>{if(i>0&&!document.querySelector(`[data-cross-step="${i-1}"]`).classList.contains('done')){result.textContent='请先完成前一步，再检查新的数据。';return}if(i===2&&+control.value!==target){result.textContent=currentSection===0?'还需调整数量，使总额恰好150元。':currentSection===1?'高度差应为7厘米：明年读数是多少？':'前两人的生日间隔需为10天；请继续调整。';return}button.classList.add('done');const done=document.querySelectorAll('[data-cross-step].done').length;result.textContent=done<3?`已完成 ${done}/3：${reading.textContent} 继续完成下一步。`:`任务完成：${reading.textContent} ${crossMission().success.replace(/^完成：/,'')}`});return}
 control.oninput=()=>{reading.textContent=`观测值 ${control.value}`;meter.style.width=control.value+'%'};
 document.querySelectorAll('[data-cross-step]').forEach(button=>button.onclick=()=>{button.classList.add('done');const done=document.querySelectorAll('[data-cross-step].done').length,success=crossMission().success.replace(/^完成：/,'');result.textContent=done<3?`已完成 ${done}/3：继续把两个学科的证据连起来。`:`任务完成：${success}`});
}
function visual(){const title=book.chapters[unit].sections[section];$('visualTitle').textContent=stageNames[stage]+' · '+title;if(verifiedLesson()){$('visualBody').innerHTML=verifiedVisual();activateVerifiedVisual();return}if(deep){$('visualBody').innerHTML=book.subject==='数学'?(unit===0?geometryVisual():extraMathVisual()):book.subject==='物理'?physicsDeepVisual():englishDeepVisual();const control=$('geoControl');if(control)control.oninput=()=>{if(book.id==='math7b'&&unit===0){const angle=Math.round(20+(+control.value)*1.4),line=document.querySelector('.moving-line'),out=$('geoReadout');if(line){line.style.transformOrigin='320px 105px';line.style.transform='rotate('+(angle-50)+'deg)'}if(out)out.textContent=angle+'°';const labels=[...document.querySelectorAll('.geometry-demo svg text')].filter(x=>x.textContent.startsWith('∠'));if(labels[0])labels[0].textContent='∠1 '+angle+'°';if(labels[1])labels[1].textContent='∠2 '+(180-angle)+'°';if(labels[2])labels[2].textContent='∠3 '+angle+'°';return}document.querySelector('.moving-line,.distance-line,.translated,.moving-point,.range-line,.shape-fill')?.style.setProperty('transform',`translateX(${(+control.value-50)/3}px) rotate(${(+control.value-50)/10}deg)`);document.querySelector('.experiment-object')?.style.setProperty('transform',`translateX(${(+control.value-50)*2}px)`);document.querySelector('.sound-wave')?.style.setProperty('--progress',`${control.value}%`)};return}if(book.subject==='数学')$('visualBody').innerHTML=`<div class="math-demo"><p>${stage===3?'改变必要条件，原结论还能成立吗？':'观察位置、方向或数量关系怎样变化'}</p><div class="axis"></div><p>${title}</p></div>`;if(book.subject==='物理')$('visualBody').innerHTML=`<div class="physics-demo"><p>${stage===3?'错误实验：同时改变了两个变量':'只改变一个条件，观察现象和读数'}</p><div class="force-object"></div><p>${title}</p></div>`;if(book.subject==='英语')$('visualBody').innerHTML=`<div class="english-demo"><p>Listen · Notice · Speak · Use</p><div class="dialogue"><span>What do you notice?</span><span>I notice the change.</span></div><p>${title}</p></div>`}
