 $('stageLabel').textContent=stage===6?'橙色支线 · 可选跨学科':'教材主线 · AI授课';$('lessonTitle').textContent=title;$('lessonCopy').textContent=copy;$('rule').textContent=verified?copy:stage===3?'规则是否成立取决于条件是否完整；反例用于看清边界。':copy;
 $('crossSubject').textContent='✦ 跨学科知识传送门 · '+(verified?.cross.subject||ch.cross.subject);$('crossTitle').textContent=verified?.cross.title||ch.cross.title;$('crossCopy').textContent=verified?.cross.copy||ch.cross.copy;
 const verifiedStage=verified?.stages[stage],spec=window.StudyMateKnowledgeEngine?.get(book.subject,currentKnowledge()),variant=!verified&&stage===7?window.StudyMateMasteryEngine?.variant(book.subject,currentKnowledge()):null;
